package com.fitnutri.backend.records.food;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.ProfileService;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;
class DishMutationIT extends PostgresIntegrationSupport {
 @Autowired FoodEntryMutationService mutations;@Autowired FoodEntryV2Service create;@Autowired FoodEntryPreviewService previews;@Autowired FoodSnapshotReader snapshots;@Autowired FoodRecordService legacy;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired FoodReferenceRepository references;@Autowired FoodDatasetRepository datasets;@Autowired JdbcTemplate jdbc;
 User owner;FoodReference a,b;FoodEntryInputs.Dish original;FoodEntryInputs.BatchRequest creation;long root;SubmissionReceiptV2Response proof;
 final LocalDate date=LocalDate.of(2020,1,2);
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);a=FoodV2TestFixtures.reference(datasets,references,"1000");b=FoodV2TestFixtures.reference(datasets,references,"400");original=new FoodEntryInputs.Dish(UUID.randomUUID(),"Synthetic same name",MealType.LUNCH,"FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",3),List.of(new FoodEntryInputs.Ingredient(UUID.randomUUID(),a.getId().toString(),new BigDecimal("300"),null,null),new FoodEntryInputs.Ingredient(UUID.randomUUID(),b.getId().toString(),new BigDecimal("150"),null,null)),null);creation=request(original);proof=create.createBatchV2(owner.getId(),creation);root=Long.parseLong(proof.roots().getFirst().id());}
 FoodEntryInputs.BatchRequest request(FoodEntryInputs.Dish entry){var input=new FoodEntryInputs.PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,List.of(entry));return new FoodEntryInputs.BatchRequest(UUID.randomUUID(),date,input.zone(),input.source(),input.entries(),previews.previewNewBatch(owner.getId(),input).fingerprint());}
 FoodEntryInputs.Dish dish(String name,MealType meal,List<FoodEntryInputs.Ingredient> ingredients){return new FoodEntryInputs.Dish(original.clientEntryId(),name,meal,original.inputMode(),original.portion(),ingredients,null);}
 FoodEntryInputs.UpdateRequest update(long version,FoodEntryInputs.Dish entry,LocalDate recordDate,boolean calculation){String fp=calculation?previews.previewOwnedRoot(owner.getId(),"dish",root,new FoodEntryInputs.CorrectionRequest(version,recordDate,"Australia/Sydney",entry)).fingerprint():null;return new FoodEntryInputs.UpdateRequest(version,recordDate,"Australia/Sydney",entry,fp);}
 long leaf(UUID uuid){return jdbc.queryForObject("SELECT id FROM food_record WHERE user_id=? AND client_entry_id=?",Long.class,owner.getId(),uuid);}
 @Test void metadataAndDateMealChangesPreserveSnapshotsAndBumpOnlyTheOwnedRootOnce(){
  var otherDish=new FoodEntryInputs.Dish(UUID.randomUUID(),original.name(),original.mealType(),original.inputMode(),original.portion(),original.ingredients().stream().map(i->new FoodEntryInputs.Ingredient(UUID.randomUUID(),i.referenceId(),i.inputGrams(),null,null)).toList(),null);var otherProof=create.createBatchV2(owner.getId(),request(otherDish));long otherRoot=Long.parseLong(otherProof.roots().getFirst().id());var untouched=snapshots.detailForReuse(owner.getId(),"dish",otherRoot);long firstLeaf=leaf(original.ingredients().getFirst().clientEntryId());jdbc.update("UPDATE food_record SET energy_kj=123.456 WHERE id=?",firstLeaf);var changed=dish("Renamed occurrence",MealType.DINNER,original.ingredients());var result=mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date.minusDays(1),false));assertEquals(1,result.version());assertEquals(new BigDecimal("323.456"),result.preview().totals().energyKj());assertEquals(date.minusDays(1),result.recordDate());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM food_record WHERE dish_id=? AND meal_type='DINNER' AND recorded_date=?",Long.class,root,date.minusDays(1)));assertEquals(original.clientEntryId(),result.input().get("clientEntryId"));assertEquals(proof.roots(),create.createBatchV2(owner.getId(),creation).roots());assertEquals(untouched,snapshots.detailForReuse(owner.getId(),"dish",otherRoot));var stolen=dish(changed.name(),changed.mealType(),List.of(otherDish.ingredients().getFirst(),original.ingredients().get(1)));assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,update(1,stolen,date.minusDays(1),true))).code());assertEquals(untouched,snapshots.detailForReuse(owner.getId(),"dish",otherRoot));
 }
 @Test void calculationChangeRequiresReviewNoopDoesNotIncrementAndStaleVersionConflicts(){var first=original.ingredients().getFirst();var changedIngredient=new FoodEntryInputs.Ingredient(first.clientEntryId(),first.referenceId(),new BigDecimal("600"),null,null);var changed=dish(original.name(),MealType.LUNCH,List.of(changedIngredient,original.ingredients().get(1)));assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date,false)));var result=mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date,true));assertEquals(1,result.version());assertEquals(new BigDecimal("2200.000"),result.preview().totals().energyKj());assertEquals(0,jdbc.queryForObject("SELECT version FROM food_record WHERE id=?",Long.class,leaf(original.ingredients().get(1).clientEntryId())));var noop=mutations.updateOwnedRoot(owner.getId(),"dish",root,update(1,changed,date,false));assertEquals(result,noop);assertEquals("VERSION_CONFLICT",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date,false))).code());}
 @Test void removeAndAddSoftDeleteOldIdentityAndCannotReintroduceIt(){var newIngredient=new FoodEntryInputs.Ingredient(UUID.randomUUID(),a.getId().toString(),new BigDecimal("60"),null,null);var entry=dish(original.name(),MealType.LUNCH,List.of(newIngredient,original.ingredients().get(1)));var result=mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,entry,date,true));assertEquals(1,result.version());assertNotNull(jdbc.queryForObject("SELECT deleted_at FROM food_record WHERE id=?",java.sql.Timestamp.class,leaf(original.ingredients().getFirst().clientEntryId())));assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,update(1,original,date,true))).code());assertEquals(result,snapshots.detailForReuse(owner.getId(),"dish",root));}
 @Test void inactiveOriginalOnlyAndForeignRootOrChildCannotBypassScope(){a.setActive(false);references.saveAndFlush(a);var old=original.ingredients().getFirst();var changed=dish(original.name(),MealType.LUNCH,List.of(new FoodEntryInputs.Ingredient(old.clientEntryId(),old.referenceId(),new BigDecimal("600"),null,null),original.ingredients().get(1)));assertEquals(1,mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date,true)).version());var newRow=dish(original.name(),MealType.LUNCH,List.of(new FoodEntryInputs.Ingredient(UUID.randomUUID(),old.referenceId(),BigDecimal.ONE,null,null)));assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,update(1,newRow,date,true))).code());var other=FoodV2TestFixtures.owner(users,profiles);assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->mutations.updateOwnedRoot(other.getId(),"dish",root,update(1,changed,date,false))).code());}
 @Test void legacyChildWritesAreBlockedAndRootDeleteIsAtomicAndIdempotent(){long leaf=leaf(original.ingredients().getFirst().clientEntryId());assertEquals("GROUP_EDIT_REQUIRED",assertThrows(BusinessException.class,()->legacy.updateOwned(owner.getId(),leaf,new UpdateFoodRecordRequest(0L,a.getId().toString(),new BigDecimal("100"),MealType.LUNCH,date,"Australia/Sydney"))).code());assertEquals("GROUP_EDIT_REQUIRED",assertThrows(BusinessException.class,()->legacy.softDeleteOwned(owner.getId(),leaf,0L)).code());mutations.softDeleteOwnedRoot(owner.getId(),"dish",root,0L);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM food_record WHERE dish_id=? AND deleted_at IS NULL",Long.class,root));assertThrows(BusinessException.class,()->snapshots.detailForReuse(owner.getId(),"dish",root));mutations.softDeleteOwnedRoot(owner.getId(),"dish",root,0L);assertEquals(1,jdbc.queryForObject("SELECT version FROM food_dish_record WHERE id=?",Long.class,root));assertEquals(proof.leaves(),create.createBatchV2(owner.getId(),creation).leaves());}
 @Test void twoConcurrentEditorsCannotOverwriteTheOtherVersion()throws Exception{var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var attempts=new ArrayList<Future<String>>();for(String name:List.of("Editor A","Editor B"))attempts.add(pool.submit(()->{start.await();try{var changed=dish(name,MealType.LUNCH,original.ingredients());return "OK:"+mutations.updateOwnedRoot(owner.getId(),"dish",root,update(0,changed,date,false)).version();}catch(BusinessException e){return e.code();}}));start.countDown();var results=Set.of(attempts.get(0).get(20,TimeUnit.SECONDS),attempts.get(1).get(20,TimeUnit.SECONDS));assertEquals(Set.of("OK:1","VERSION_CONFLICT"),results);assertEquals(1,snapshots.detailForReuse(owner.getId(),"dish",root).version());}}
 @Test void lateChildUpdateFailureRollsBackParentAndEarlierChild(){
  var before=snapshots.detailForReuse(owner.getId(),"dish",root);var changed=dish(original.name(),MealType.DINNER,original.ingredients().stream().map(i->new FoodEntryInputs.Ingredient(i.clientEntryId(),i.referenceId(),i.inputGrams().multiply(BigDecimal.valueOf(2)),null,null)).toList());var request=update(0,changed,date.minusDays(1),true);String suffix=UUID.randomUUID().toString().replace("-","");String function="test_dish_update_"+suffix,trigger="test_dish_update_trigger_"+suffix;jdbc.execute("CREATE FUNCTION "+function+"() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Synthetic later update rejection' USING ERRCODE='23514'; END$$");jdbc.execute("CREATE TRIGGER "+trigger+" BEFORE UPDATE ON food_record FOR EACH ROW WHEN (NEW.user_id="+owner.getId()+" AND NEW.food_reference_id="+b.getId()+") EXECUTE FUNCTION "+function+"()");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->mutations.updateOwnedRoot(owner.getId(),"dish",root,request));assertEquals(before,snapshots.detailForReuse(owner.getId(),"dish",root));assertEquals(proof.roots(),create.createBatchV2(owner.getId(),creation).roots());}finally{jdbc.execute("DROP TRIGGER "+trigger+" ON food_record");jdbc.execute("DROP FUNCTION "+function+"()");}
 }
 @Test void independentSingleV2UpdateAndDeleteUseOneRootVersion(){
  var uuid=UUID.randomUUID();var single=new FoodEntryInputs.Single(uuid,a.getId().toString(),new BigDecimal("100"),MealType.SNACK,null,null);var input=new FoodEntryInputs.PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,List.of(single));var fp=previews.previewNewBatch(owner.getId(),input).fingerprint();var created=create.createBatchV2(owner.getId(),new FoodEntryInputs.BatchRequest(UUID.randomUUID(),date,input.zone(),input.source(),input.entries(),fp));long id=Long.parseLong(created.roots().getFirst().id());var changed=new FoodEntryInputs.Single(uuid,a.getId().toString(),new BigDecimal("200"),MealType.DINNER,"APPROXIMATE",null);var current=previews.previewOwnedRoot(owner.getId(),"single",id,new FoodEntryInputs.CorrectionRequest(0L,date.minusDays(1),input.zone(),changed));var result=mutations.updateOwnedRoot(owner.getId(),"single",id,new FoodEntryInputs.UpdateRequest(0L,date.minusDays(1),input.zone(),changed,current.fingerprint()));assertEquals(1,result.version());assertEquals(new BigDecimal("2000.000"),result.preview().totals().energyKj());assertEquals(result,mutations.updateOwnedRoot(owner.getId(),"single",id,new FoodEntryInputs.UpdateRequest(1L,date.minusDays(1),input.zone(),changed,null)));assertThrows(BusinessException.class,()->mutations.softDeleteOwnedRoot(owner.getId(),"single",id,0L));mutations.softDeleteOwnedRoot(owner.getId(),"single",id,1L);mutations.softDeleteOwnedRoot(owner.getId(),"single",id,0L);assertEquals(2,jdbc.queryForObject("SELECT version FROM food_record WHERE id=?",Long.class,id));
 }
}
